def payment_events_iso_day(value):
    return type(value) is str and len(value) == 10 and value[4] == '-' and value[7] == '-'

def apply(inputs, premises):
    component = inputs['component_id']
    view = inputs['view']
    public = inputs['public_case']
    kernel = inputs['kernel']
    facts = []
    negatives = []
    witnesses = []
    reasons = []
    complete = True
    if type(view) is not dict or view.get('extraction_status') != 'complete':
        return part([], [], [], False, [component + '_unread_or_ambiguous'])
    if not support(witnesses, view, public, True):
        complete = False
        add(reasons, component + '_complete_view_requires_current_facts_witness')
    records = view.get('payments')
    if type(records) is not list:
        return part(facts, negatives, witnesses, False, reasons + ['payment_channel_unread'])
    pt = target_payment(kernel)
    st = target_service(kernel)
    pc = 0
    sc = 0
    for index, record in enumerate(records):
        if not support(witnesses, record, public, True):
            complete = False
            continue
        payer = record.get('payer')
        payees = record.get('payees')
        amount = record.get('amount')
        precision = record.get('temporal_precision')
        date = record.get('payment_date')
        year = record.get('stated_year')
        if (payer is not None and type(payer) is not str) or type(payees) is not list or not all(type(x) is str for x in payees) or (amount is not None and type(amount) not in (int, float)) or precision not in ('full_date', 'year_only', 'unstated'):
            complete = False
            continue
        if precision == 'full_date' and not payment_events_iso_day(date):
            complete = False
            add(reasons, 'payment_full_date_invalid_or_unstated')
            continue
        if precision == 'year_only' and (type(year) is not int or date is not None):
            complete = False
            add(reasons, 'payment_year_is_not_payment_day')
            continue
        if precision == 'unstated' and date is not None:
            complete = False
            continue
        payment = 'source_payment_' + str(index)
        if record.get('is_query_payment') is True:
            pc += 1
            if type(pt) is str:
                payment = pt
        put(facts, 'payment_', [payment])
        if type(payer) is str:
            put(facts, 'agent_', [payment, payer])
        for payee in payees:
            put(facts, 'patient_', [payment, payee])
        if type(amount) in (int, float):
            put(facts, 'amount_', [payment, amount])
        if type(record.get('medium')) is str:
            put(facts, 'means_', [payment, record.get('medium')])
        if precision == 'full_date':
            put(facts, 'start_', [payment, date])
        linked = record.get('linked_service')
        if type(linked) is dict:
            worker = linked.get('worker')
            employer = linked.get('employer')
            if type(worker) is not str or type(employer) is not str or linked.get('role_basis') != 'payer_employer_payee_worker' or (type(payer) is str and employer != payer) or (len(payees) > 0 and worker not in payees):
                complete = False
                add(reasons, 'linked_service_roles_not_source_coherent')
                continue
            service = 'source_payment_service_' + str(index)
            if linked.get('is_query_service') is True:
                sc += 1
                if type(st) is str:
                    service = st
            put(facts, 'service_', [service])
            put(facts, 'agent_', [service, worker])
            put(facts, 'patient_', [service, employer])
            if type(linked.get('service_kind')) is str:
                put(facts, 'purpose_', [service, linked.get('service_kind')])
            if type(linked.get('service_venue')) is str:
                put(facts, 'location_', [service, linked.get('service_venue')])
            if type(linked.get('location')) is str:
                put(facts, 'location_', [service, linked.get('location')])
                if type(linked.get('country')) is str:
                    put(facts, 'country_', [linked.get('location'), linked.get('country')])
            if type(linked.get('start_date')) is str:
                put(facts, 'start_', [service, linked.get('start_date')])
            if type(linked.get('end_date')) is str:
                put(facts, 'end_', [service, linked.get('end_date')])
            put(facts, 'purpose_', [payment, service])
        elif type(record.get('purpose_entity')) is str:
            put(facts, 'purpose_', [payment, record.get('purpose_entity')])
    if type(pt) is str and len(records) > 0 and pc != 1:
        complete = False
        add(reasons, 'queried_payment_role_not_uniquely_aligned')
    if sc > 1:
        complete = False
        add(reasons, 'queried_service_role_not_uniquely_aligned')
    if not complete:
        add(reasons, component + '_one_or_more_records_unread_or_invalid')
    return part(facts, negatives, witnesses, complete, reasons)

def apply(inputs, premises):
    component = inputs['component_id']
    view = inputs['view']
    public = inputs['public_case']
    kernel = inputs['kernel']
    facts = []
    negatives = []
    witnesses = []
    reasons = []
    complete = True
    if type(view) is not dict or view.get('extraction_status') != 'complete':
        return part([], [], [], False, [component + '_unread_or_ambiguous'])
    if not support(witnesses, view, public, True):
        complete = False
        add(reasons, component + '_complete_view_requires_current_facts_witness')
    records = view.get('exact_givens')
    boundaries = view.get('boundary_statements')
    if type(records) is not list or type(boundaries) is not list:
        return part(facts, negatives, witnesses, False, reasons + ['explicit_legal_channel_unread'])
    bases = {'s151_b': 'section151_b_exact', 's151_b_applies': 'section151_b_applies_exact', 's151_c_applies': 'section151_c_applies_exact', 's152_c_1': 'section152_c_1_exact', 's63_f_1_A': 'section63_f_1_A_exact', 's63_f_1_B': 'section63_f_1_B_exact'}
    seen = set()
    for record in records:
        if not support(witnesses, record, public, True):
            complete = False
            continue
        name = record.get('predicate')
        args = record.get('arguments')
        polarity = record.get('polarity')
        if not valid_given(name, args) or record.get('basis') != bases.get(name) or polarity not in ('positive', 'negative'):
            complete = False
            add(reasons, 'exact_legal_basis_or_signature_invalid')
            continue
        if is_target_given(kernel, name):
            complete = False
            add(reasons, 'target_legal_query_cannot_be_reasserted_as_fact')
            continue
        key = (name, tuple(args), polarity)
        if key not in seen:
            seen.add(key)
            row = {'predicate': name, 'arguments': list(args)}
            add(negatives if polarity == 'negative' else facts, row)
    for record in boundaries:
        if not support(witnesses, record, public, True) or record.get('kind') not in ('section151_general', 'section151_d', 'section151_other', 'section63_f_general'):
            complete = False
    if not complete:
        add(reasons, component + '_one_or_more_records_unread_or_invalid')
    return part(facts, negatives, witnesses, complete, reasons)

