def apply(inputs, premises):
    component = inputs['component_id']
    view = inputs['view']
    public = inputs['public_case']
    kernel = inputs['kernel']
    facts = []
    negatives = []
    witnesses = []
    reasons = []
    complete = True
    if type(view) is not dict or view.get('extraction_status') != 'complete':
        return part([], [], [], False, [component + '_unread_or_ambiguous'])
    if not support(witnesses, view, public, True):
        complete = False
    payments = view.get('payments')
    services = view.get('services')
    conditions = view.get('conditions')
    terminations = view.get('terminations')
    retirements = view.get('retirements')
    if type(payments) is not list or type(services) is not list or type(conditions) is not list or type(terminations) is not list or type(retirements) is not list:
        return part(facts, negatives, witnesses, False, ['employment_occurrence_channels_unread'])
    st = target_service(kernel)
    pt = target_payment(kernel)
    sc = 0
    pc = 0
    service_ids = {}
    for index, record in enumerate(services):
        if not support(witnesses, record, public, True):
            complete = False
            continue
        local_id = record.get('local_id')
        worker = record.get('worker')
        employer = record.get('employer')
        if type(local_id) is not str or local_id in service_ids or type(worker) is not str or type(employer) is not str:
            complete = False
            continue
        event = 'employment_service_' + str(index)
        if record.get('is_query_service') is True:
            sc += 1
            if type(st) is str:
                event = st
        service_ids[local_id] = event
        put(facts, 'service_', [event])
        put(facts, 'agent_', [event, worker])
        put(facts, 'patient_', [event, employer])
        if type(record.get('service_kind')) is str:
            put(facts, 'purpose_', [event, record.get('service_kind')])
        if type(record.get('service_venue')) is str:
            put(facts, 'location_', [event, record.get('service_venue')])
        if type(record.get('location')) is str:
            put(facts, 'location_', [event, record.get('location')])
            if type(record.get('country')) is str:
                put(facts, 'country_', [record.get('location'), record.get('country')])
        if type(record.get('start_date')) is str:
            put(facts, 'start_', [event, record.get('start_date')])
        if type(record.get('end_date')) is str:
            put(facts, 'end_', [event, record.get('end_date')])
    condition_ids = {}
    for index, record in enumerate(conditions):
        if not support(witnesses, record, public, True):
            complete = False
            continue
        local_id = record.get('local_id')
        kind = record.get('kind')
        person = record.get('person')
        if type(local_id) is not str or local_id in condition_ids or kind not in ('disability', 'death') or type(person) is not str:
            complete = False
            continue
        event = 'employment_condition_' + str(index)
        condition_ids[local_id] = event
        put(facts, kind + '_', [event])
        put(facts, 'agent_', [event, person])
        if type(record.get('date')) is str:
            put(facts, 'start_', [event, record.get('date')])
    for index, record in enumerate(payments):
        if not support(witnesses, record, public, True):
            complete = False
            continue
        precision = record.get('temporal_precision')
        date = record.get('payment_date')
        year = record.get('stated_year')
        if precision not in ('full_date', 'year_only', 'unstated') or (precision == 'full_date' and not payment_service_events_iso_day(date)) or (precision == 'year_only' and (type(year) is not int or date is not None)) or (precision == 'unstated' and date is not None):
            complete = False
            add(reasons, 'payment_temporal_precision_invalid')
            continue
        payment = 'employment_payment_' + str(index)
        if record.get('is_query_payment') is True:
            pc += 1
            if type(pt) is str:
                payment = pt
        put(facts, 'payment_', [payment])
        if type(record.get('payer')) is str:
            put(facts, 'agent_', [payment, record.get('payer')])
        if type(record.get('payee')) is str:
            put(facts, 'patient_', [payment, record.get('payee')])
        if type(record.get('amount')) in (int, float):
            put(facts, 'amount_', [payment, record.get('amount')])
        if type(record.get('medium')) is str:
            put(facts, 'means_', [payment, record.get('medium')])
        if precision == 'full_date':
            put(facts, 'start_', [payment, date])
        linked = record.get('service_local_id')
        if type(linked) is str:
            if linked in service_ids:
                put(facts, 'purpose_', [payment, service_ids[linked]])
            else:
                complete = False
                add(reasons, 'payment_links_unknown_service')
    for index, record in enumerate(terminations):
        if not support(witnesses, record, public, True):
            complete = False
            continue
        service_id = record.get('service_local_id')
        condition_id = record.get('condition_local_id')
        employer = record.get('employer')
        if service_id not in service_ids or type(employer) is not str or (condition_id is not None and condition_id not in condition_ids):
            complete = False
            continue
        event = 'employment_termination_' + str(index)
        put(facts, 'termination_', [event])
        put(facts, 'agent_', [event, employer])
        put(facts, 'patient_', [event, service_ids[service_id]])
        if type(condition_id) is str:
            put(facts, 'reason_', [event, condition_ids[condition_id]])
        if type(record.get('termination_date')) is str:
            put(facts, 'start_', [event, record.get('termination_date')])
    for index, record in enumerate(retirements):
        if not support(witnesses, record, public, True) or type(record.get('person')) is not str:
            complete = False
            continue
        condition_id = record.get('condition_local_id')
        if condition_id is not None and condition_id not in condition_ids:
            complete = False
            continue
        event = 'employment_retirement_' + str(index)
        put(facts, 'retirement_', [event])
        put(facts, 'agent_', [event, record.get('person')])
        if type(condition_id) is str:
            put(facts, 'reason_', [event, condition_ids[condition_id]])
        if type(record.get('retirement_date')) is str:
            put(facts, 'start_', [event, record.get('retirement_date')])
    if type(st) is str and len(services) > 0 and sc != 1:
        complete = False
        add(reasons, 'queried_service_role_not_uniquely_aligned')
    if type(pt) is str and len(payments) > 0 and pc != 1:
        complete = False
        add(reasons, 'queried_payment_role_not_uniquely_aligned')
    if not complete:
        add(reasons, component + '_one_or_more_records_unread_or_invalid')
    return part(facts, negatives, witnesses, complete, reasons)

def apply(inputs, premises):
    component = inputs['component_id']
    view = inputs['view']
    public = inputs['public_case']
    facts = []
    negatives = []
    witnesses = []
    reasons = []
    complete = True
    if type(view) is not dict or view.get('extraction_status') != 'complete':
        return part([], [], [], False, [component + '_unread_or_ambiguous'])
    if not support(witnesses, view, public, True):
        complete = False
    records = view.get('records')
    if type(records) is not list:
        return part(facts, negatives, witnesses, False, ['source_context_channel_unread'])
    names = {'american_employer': 'american_employer_', 'business': 'business_', 'business_trust': 'business_trust_', 'citizenship': 'citizenship_', 'international_organization': 'international_organization_', 'itemize_deductions': 'itemize_deductions_', 'medical_institution': 'medical_institution_', 'migration': 'migration_', 'nonresident_alien': 'nonresident_alien_', 'nurses_training_school': 'nurses_training_school_', 'plan': 'plan_', 'unemployment_compensation_agreement': 'unemployment_compensation_agreement_'}
    for index, record in enumerate(records):
        kind = record.get('kind')
        subject = record.get('subject')
        related = record.get('related')
        participants = record.get('participants')
        beneficiaries = record.get('beneficiaries')
        if not support(witnesses, record, public, True) or kind not in names or type(subject) is not str or type(participants) is not list or type(beneficiaries) is not list or not all(type(x) is str for x in participants + beneficiaries):
            complete = False
            continue
        event = 'source_context_' + kind + '_' + str(index)
        put(facts, names[kind], [event])
        put(facts, 'agent_', [event, subject])
        if kind == 'citizenship':
            if type(related) is str:
                put(facts, 'patient_', [event, related])
            else:
                complete = False
        elif kind == 'migration':
            if type(related) is str:
                put(facts, 'destination_', [event, related])
            else:
                complete = False
            if type(record.get('purpose')) is str:
                put(facts, 'purpose_', [event, record.get('purpose')])
        elif kind == 'business':
            if type(record.get('category')) is str:
                put(facts, 'type_', [event, record.get('category')])
        elif kind == 'plan':
            if type(record.get('purpose')) is str:
                put(facts, 'purpose_', [event, record.get('purpose')])
            for person in beneficiaries:
                put(facts, 'beneficiary_', [event, person])
        elif kind == 'unemployment_compensation_agreement':
            if len(participants) < 2:
                complete = False
            for participant in participants:
                put(facts, 'agent_', [event, participant])
        elif type(related) is str:
            put(facts, 'patient_', [event, related])
        if type(record.get('start_date')) is str:
            put(facts, 'start_', [event, record.get('start_date')])
        if type(record.get('end_date')) is str:
            put(facts, 'end_', [event, record.get('end_date')])
    if not complete:
        add(reasons, component + '_one_or_more_records_unread_or_invalid')
    return part(facts, negatives, witnesses, complete, reasons)
